"""Generate the compact serial footer font. Requires Pillow and the bundled Noto font."""
from pathlib import Path
from PIL import Image,ImageDraw,ImageFont
root=Path(__file__).resolve().parents[1]
font=ImageFont.truetype(str(root/'assets/NotoSansCJKsc-Regular.otf'),12)
chars=sorted(set(''.join(chr(i) for i in range(32,127))+'待发送成功失败已排队更新接收数据等待'),key=ord)
bitmap=[];glyphs=[' {0},']
for char in chars:
 l,t,r,b=font.getbbox(char,anchor='ls');w,h=r-l,b-t;img=Image.new('L',(max(1,w),max(1,h)),0);ImageDraw.Draw(img).text((-l,-t),char,font=font,fill=255,anchor='ls');px=[round(v*3/255) for v in img.tobytes()] if w*h else [];offset=len(bitmap)
 for i in range(0,len(px),4):
  byte=0
  for j,v in enumerate(px[i:i+4]):byte|=v<<(6-2*j)
  bitmap.append(byte)
 glyphs.append(' {.bitmap_index=%d,.adv_w=%d,.box_w=%d,.box_h=%d,.ofs_x=%d,.ofs_y=%d},'%(offset,round(font.getlength(char)*16),w,h,l,-b))
text=['/* Generated by tools/generate_serial_status_font.py; Noto SIL OFL 1.1. */','#include "lvgl.h"','static const uint8_t bitmap[]={']
text+=[' '+','.join(map(str,bitmap[i:i+24]))+',' for i in range(0,len(bitmap),24)]
text+=['};','static const lv_font_fmt_txt_glyph_dsc_t glyphs[]={',*glyphs,'};','static const uint16_t unicodes[]={'+','.join(str(ord(c)-32) for c in chars)+'};','static const lv_font_fmt_txt_cmap_t maps[]={{.range_start=32,.range_length=%d,.glyph_id_start=1,.unicode_list=unicodes,.list_length=%d,.type=LV_FONT_FMT_TXT_CMAP_SPARSE_TINY}};'%(ord(chars[-1])-31,len(chars)),'static lv_font_fmt_txt_glyph_cache_t cache;','static lv_font_fmt_txt_dsc_t dsc={.glyph_bitmap=bitmap,.glyph_dsc=glyphs,.cmaps=maps,.cmap_num=1,.bpp=2,.cache=&cache};','const lv_font_t font_serial_status12={.get_glyph_dsc=lv_font_get_glyph_dsc_fmt_txt,.get_glyph_bitmap=lv_font_get_bitmap_fmt_txt,.line_height=16,.base_line=3,.dsc=&dsc,.fallback=&lv_font_montserrat_14};']
(root/'main/apps/serial/serial_status_font.c').write_text('\n'.join(text)+'\n',encoding='utf-8')
